"""Probe, fully decode, and visually inspect the actual pending encoded movie."""
import base64
import json
from pathlib import Path
from media import probe
from renderer import execute


def stream_duration_ms(stream, info):
    if not stream:
        return None
    value = stream.get('duration')
    if value not in (None, 'N/A'):
        try:
            return round(float(value) * 1000)
        except (TypeError, ValueError):
            return None
    duration_ts = stream.get('duration_ts')
    time_base = stream.get('time_base')
    if duration_ts is not None and time_base and '/' in str(time_base):
        try:
            numerator, denominator = (int(part) for part in str(time_base).split('/', 1))
            if denominator:
                return round(int(duration_ts) * numerator * 1000 / denominator)
        except (TypeError, ValueError):
            return None
    return None


def media_duration_checks(info, expected_ms, fps):
    """Compare real audio-stream coverage and container duration to the plan."""
    audio = next((s for s in info.get('streams', []) if s.get('codec_type') == 'audio'), None)
    tolerance = max(150, round(3000 / fps)) if fps else 150
    audio_ms = stream_duration_ms(audio, info)
    container_ms = stream_duration_ms(info.get('format'), info)
    try:
        audio_start_ms = round(float(audio.get('start_time', 0) or 0) * 1000) if audio else None
    except (TypeError, ValueError):
        audio_start_ms = None
    return {
        'audio_ms': audio_ms,
        'audio_start_ms': audio_start_ms,
        'container_ms': container_ms,
        'expected_ms': expected_ms,
        'tolerance_ms': tolerance,
        'audio_ok': audio_ms is not None and abs(audio_ms - expected_ms) <= tolerance
                    and (audio_start_ms is None or audio_start_ms <= tolerance),
        'container_ok': container_ms is not None and abs(container_ms - expected_ms) <= tolerance,
    }


def verify(pending, t, derived, inventory, requirements, config, run_dir, model):
    movie = Path(pending)
    if not movie.is_file() or movie.stat().st_size <= 10000:
        raise ValueError('Movie is missing or empty')
    info = probe(movie, config)
    video = next((s for s in info['streams'] if s['codec_type'] == 'video'), None)
    audio = next((s for s in info['streams'] if s['codec_type'] == 'audio'), None)
    duration = derived['computed_duration_ms']
    actual_ms = round(float(video.get('duration', info['format']['duration'])) * 1000) if video else None
    fps = video.get('avg_frame_rate', '0/0') if video else '0/0'
    numer, denom = map(int, fps.split('/'))
    actual_fps = numer / denom if denom else 0
    checks = []
    def check(name, condition, actual, req=None, evidence=None):
        checks.append({'check_id': name, 'requirement_id': req, 'status': 'pass' if condition else 'fail', 'actual': actual, 'evidence': evidence or str(movie)})
    check('nonempty', movie.stat().st_size > 10000, movie.stat().st_size)
    check('video_stream', bool(video) and video['width'] == t.output.width and video['height'] == t.output.height and video['codec_name'] == 'h264' and abs(actual_fps-t.output.fps) < .01,
          {'video': video, 'fps': actual_fps})
    check('video_duration_ms', actual_ms is not None and abs(actual_ms-duration) <= max(100, 2000/t.output.fps), {'video_ms': actual_ms, 'container_ms': round(float(info['format']['duration'])*1000), 'expected_ms': duration})
    check('audio_stream', bool(audio) and audio['codec_name'] == 'aac', audio)
    coverage = media_duration_checks(info, duration, t.output.fps)
    check('audio_duration_ms', coverage['audio_ok'], coverage)
    check('container_duration_ms', coverage['container_ok'], coverage)
    execute([config.ffmpeg, '-hide_banner', '-v', 'error', '-i', str(movie), '-f', 'null', '-'], run_dir, f'decode_v{t.version}', config.command_timeout_s)
    check('full_decode', True, 'ffmpeg returned exit 0', evidence='commands/*decode*.result.json')
    points = {0, max(0, duration-100), 1000, max(0, duration-1000)}
    for pos in derived['clip_positions']:
        points.add((pos['start_ms'] + pos['end_ms']) // 2)
        points.add(max(0, pos['end_ms']-150))
        points.add(min(duration-100, pos['end_ms']+150))
    folder = Path(run_dir) / 'verification_frames'
    folder.mkdir(exist_ok=True)
    frames = []
    for ms in sorted(p for p in points if 0 <= p < duration):
        frame = folder / f'v{t.version}_{ms}.jpg'
        execute([config.ffmpeg, '-hide_banner', '-loglevel', 'error', '-y', '-ss', f'{ms/1000:.3f}', '-i', str(movie), '-frames:v', '1', '-q:v', '3', str(frame)], run_dir, f'frame_v{t.version}_{ms}', config.command_timeout_s)
        frames.append({'time_ms': ms, 'path': str(frame)})
    title = next((c.text for c in t.captions if c.start_ms == 0), None)
    ending = next((c.text for c in t.captions if c.end_ms == duration), None)
    first = t.clips[0].kind
    title_ms = min(1000, max(0, duration - 100))
    ending_ms = max(0, duration - 1000)
    instruction = ['Inspect ONLY these frames sampled from the ACTUAL encoded movie.']
    if title is not None:
        instruction.append(f'Title at {title_ms}ms should visually read exactly {title!r}.')
    if ending is not None:
        instruction.append(f'Ending near {ending_ms}ms should read exactly {ending!r}.')
    instruction.append(f'First clip type is {first} (static image has DEMO_STILL; video has dynamic DEMO_01/02/03). Inspect first/last order. Return only JSON with booleans title_visible, ending_visible, order_visible and uncertainty; do not claim unobserved frames verified.')
    content = [{'type': 'input_text', 'text': ' '.join(instruction)}]
    wanted = [100]
    if title is not None:
        wanted.append(title_ms)
    if ending is not None:
        wanted.append(ending_ms)
    for ms in dict.fromkeys(wanted):
        frame = min(frames, key=lambda x: abs(x['time_ms']-ms))
        content += [{'type': 'input_text', 'text': f"Movie timestamp {frame['time_ms']}ms evidence {frame['path']}"}, {'type': 'input_image', 'image_url': 'data:image/jpeg;base64,' + base64.b64encode(Path(frame['path']).read_bytes()).decode()}]
    result = model.respond([{'role': 'user', 'content': content}], purpose='encoded_movie_visual_review').output_text
    try:
        observed = json.loads(result.strip().removeprefix('```json').removesuffix('```').strip())
    except ValueError:
        observed = {'uncertainty': result}
    visual_keys = ['order_visible']
    if title is not None:
        visual_keys.append('title_visible')
    if ending is not None:
        visual_keys.append('ending_visible')
    for key in visual_keys:
        check('visual_'+key, observed.get(key) is True, observed, evidence=frames)
    for req in requirements['hard_constraints']:
        field = req['field']
        associated = ['video_stream', 'video_duration_ms', 'audio_stream', 'audio_duration_ms', 'container_duration_ms', 'full_decode']
        if field.startswith('title_') and title is not None:
            associated += ['visual_title_visible']
        if field.startswith('ending_') and ending is not None:
            associated += ['visual_ending_visible']
        if field == 'clip_order':
            associated += ['visual_order_visible']
        if field in ('bgm_gain_db', 'video_gain_db', 'video_mute', 'bgm_fade_in_ms', 'bgm_fade_out_ms'):
            evidence = {'validated_timeline': f'timeline_v{t.version}.json', 'controlled_source_graph': 'commands/*render*.argv.json', 'decoded_audio': bool(audio), 'duration_check': coverage}
        else:
            evidence = {'timeline_semantic_check': next(c for c in derived['constraint_checks'] if c['requirement_id'] == req['requirement_id']), 'movie_frames': frames if field in ('clip_order', 'title_text', 'ending_text') else []}
        check('hard_'+req['requirement_id'], all(next(c for c in checks if c['check_id'] == n)['status'] == 'pass' for n in associated), {'field': field, 'expected': req['expected']}, req['requirement_id'], evidence)
    return {'version': t.version, 'status': 'pass' if all(c['status'] == 'pass' for c in checks) else 'needs_review', 'checks': checks, 'probe': {'video_duration_ms': actual_ms, 'container_duration_ms': round(float(info['format']['duration'])*1000)}, 'visual_review_raw': result, 'sampled_frames': frames, 'limitations': ['Sampled visual frames do not establish every intermediate frame', 'Gain is verified by controlled source graph and encoded audio presence, not isolated-source waveform separation', 'Audio coverage is checked from stream/container durations, not a per-sample silence map']}

def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))


def save(path, obj):
    Path(path).write_text(json.dumps(obj, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')


def parse_response(text):
    return json.loads(text.strip().removeprefix('```json').removesuffix('```').strip())


def verify_sources(assets):
    for a in assets['assets']:
        path = Path(assets['asset_root']) / a['relative_path']
        if not path.is_file() or sha256_file(path) != a['sha256']:
            raise ValueError(f'Source asset changed; frozen analysis invalid: {a["relative_path"]}')


def ensure_provider_checkpoints(run_dir, config):
    """Never resume/commingle planning checkpoints created under another provider."""
    expected = {'model': config.model, 'api_base': config.api_base, 'credential_env': config.api_key_env}
    for checkpoint in sorted(Path(run_dir).glob('agent_v*/checkpoint.json')):
        state = read(checkpoint)
        if state.get('runtime_config') != expected:
            raise ValueError(f'{checkpoint} was created by a legacy/different provider; use a new run directory after migration')


def completed_matches(run_dir, version, raw, assets):
    req = read(run_dir / f'requirements_v{version}.json')
    if req['raw_text'] != raw:
        raise ValueError('Completed version belongs to a different request')
    verify_sources(assets)
    t, derived = timeline.check(read(run_dir / f'timeline_v{version}.json'), assets, req)
    stored = read(run_dir / f'derived_v{version}.json')
    if derived != stored or t.asset_manifest_hash != assets['manifest_hash']:
        raise ValueError('Completed timeline/derived result changed')
    validation = read(run_dir / f'validation_v{version}.json')
    if validation['status'] != 'pass':
        raise ValueError('Completed version has no passing validation')
    output = run_dir / f'output_v{version}.mp4'
    recorded = next((x['sha256'] for x in read(run_dir / 'manifest.json')['files']
                     if x['path'] == output.name), None)
    if recorded is None or sha256_file(output) != recorded:
        raise ValueError('Completed video differs from published manifest')


def requirements(run_dir, version, raw, client):
    path = run_dir / f'requirements_v{version}.json'
    if path.exists():
        previous = read(path)
        if raw != previous['raw_text']:
            raise ValueError('Frozen requirement baseline cannot be changed')
        return previous
    parent = read(run_dir / 'requirements_v1.json') if version == 2 else None
    instruction = ('Return JSON ONLY. Supported constraint fields: ' + ', '.join(FIELDS) + '. '
                   'Extract ONLY constraints explicitly requested in this text, never fill every field or invent captions/music. '
